<script lang="ts">
  import { onMount } from 'svelte';
  import SettingsHeader from '$lib/components/SettingsHeader.svelte';
  import Icon from '$lib/components/Icon.svelte';
  import UiButton from '$lib/components/ui/UiButton.svelte';
  import UiSurface from '$lib/components/ui/UiSurface.svelte';
  import { api } from '$lib/api';
  import type { Food, MealCategory, MealPlan, MealPlanItem, Recipe, RecipeIngredient } from '$lib/types';

  type Section = 'plan' | 'recipes' | 'foods' | 'categories';
  type FoodDraft = { name: string; kcal: string; protein_g: string; carbs_g: string; fat_g: string; fiber_g: string; sugar_g: string; free_sugar_g: string; saturated_fat_g: string; sodium_mg: string; potassium_mg: string; calcium_mg: string; magnesium_mg: string; iron_mg: string; zinc_mg: string; vitamin_a_ug: string; vitamin_c_mg: string; vitamin_d_ug: string; vitamin_b12_ug: string; folate_ug: string };
  type SelectedSlot = { day: number; category: MealCategory };
  const DAYS = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];
  const emptyFood = (): FoodDraft => ({ name: '', kcal: '', protein_g: '', carbs_g: '', fat_g: '', fiber_g: '', sugar_g: '', free_sugar_g: '', saturated_fat_g: '', sodium_mg: '', potassium_mg: '', calcium_mg: '', magnesium_mg: '', iron_mg: '', zinc_mg: '', vitamin_a_ug: '', vitamin_c_mg: '', vitamin_d_ug: '', vitamin_b12_ug: '', folate_ug: '' });

  let section: Section = 'plan'; let loading = true; let saving = false; let error = ''; let notice = '';
  let categories: MealCategory[] = []; let foods: Food[] = []; let recipes: Recipe[] = []; let plans: MealPlan[] = [];
  let categoryPresetIds: Record<string, string[]> = {};
  let categoryName = ''; let foodDraft = emptyFood();
  let recipeName = ''; let recipeServings = '1'; let recipeNotes = ''; let recipeInstructions = ''; let recipeFoodId = ''; let recipeQuantity = '100'; let recipeDraft: RecipeIngredient[] = [];
  let editingRecipeId = ''; let editingRecipeDraft: RecipeIngredient[] = []; let editingRecipeFoodId = ''; let editingRecipeQuantity = '100'; let editingRecipeNotes = ''; let editingRecipeInstructions = '';
  let planName = ''; let selectedPlanId = ''; let planDraft: MealPlanItem[] = []; let planDraftPlanId = '';
  let visibleDay = 0; let selectedSlot: SelectedSlot | null = null; let slotRecipeId = ''; let slotPortion = '1'; let recipeSearch = '';
  let slotDialog: HTMLDialogElement;

  $: activeCategories = categories.filter((category) => category.is_active);
  $: activeRecipes = recipes.filter((recipe) => recipe.status === 'active');
  $: filteredSlotRecipes = activeRecipes.filter((recipe) => recipe.name.toLocaleLowerCase('de').includes(recipeSearch.trim().toLocaleLowerCase('de')));
  $: selectedPlan = plans.find((plan) => plan.id === selectedPlanId) ?? null;

  function expandPlanItems(items: MealPlanItem[]) {
    return items.flatMap((item) => (item.weekdays?.length ? item.weekdays : [0, 1, 2, 3, 4, 5, 6])
      .map((day) => ({ ...item, id: undefined, weekdays: [day] })))
      .map((item, sort_order) => ({ ...item, sort_order }));
  }
  function hydratePlan(plan: MealPlan) { selectedPlanId = plan.id; planDraftPlanId = plan.id; planDraft = expandPlanItems(plan.items); }
  async function load() {
    loading = true; error = '';
    try {
      [categories, foods, recipes, plans] = await Promise.all([api.getMealCategories(true), api.getFoods(), api.getRecipes(), api.getMealPlans()]);
      const presetLists = await Promise.all(categories.map(async (category) => [category.id, (await api.getMealCategoryRecipePresets(category.id)).map((recipe) => recipe.id)] as const));
      categoryPresetIds = Object.fromEntries(presetLists);
      const preferred = plans.find((plan) => plan.id === selectedPlanId) ?? plans.find((plan) => plan.is_active) ?? plans[0];
      if (preferred && preferred.id !== planDraftPlanId) hydratePlan(preferred);
    } catch { error = 'Die Mahlzeiten-Konfiguration konnte nicht geladen werden. Prüfe die Verbindung und versuche es erneut.'; }
    finally { loading = false; }
  }
  onMount(load);
  async function save(action: () => Promise<unknown>, success: string) { error = ''; notice = ''; saving = true; try { if (!await action()) throw new Error('empty'); notice = success; await load(); } catch { error = 'Änderung konnte nicht gespeichert werden. Deine Eingabe bleibt erhalten; versuche es erneut.'; } finally { saving = false; } }
  function foodName(id?: string | null) { return foods.find((food) => food.id === id)?.name ?? 'Unbekanntes Lebensmittel'; }
  function recipeNameFor(id?: string | null) { return recipes.find((recipe) => recipe.id === id)?.name ?? 'Unbekanntes Rezept'; }
  function nutrition(recipe: Recipe) { const n = recipe.nutrition; return n?.kcal == null ? 'Nährwerte unvollständig' : `${Math.round(Number(n.kcal))} kcal · ${Number(n.protein_g ?? 0).toFixed(1)} g Protein`; }
  function instructionSteps(value: string) { return value.split('\n').map((step) => step.trim()).filter(Boolean); }
  function nutrient(value: string) { const number = Number(value); return value.trim() !== '' && Number.isFinite(number) && number >= 0 ? number : null; }

  function addCategory() { const name = categoryName.trim(); if (!name) { error = 'Bitte gib einen Namen für den Slot ein.'; return; } save(async () => { const value = await api.createMealCategory({ name, sort_order: categories.length, is_active: true }); if (value) categoryName = ''; return value; }, 'Slot gespeichert.'); }
  function moveCategory(index: number, direction: -1 | 1) { const next = [...categories]; const target = index + direction; if (target < 0 || target >= next.length) return; [next[index], next[target]] = [next[target], next[index]]; save(() => api.reorderMealCategories(next.map((category) => category.id)), 'Reihenfolge gespeichert.'); }
  function setCategoryActive(category: MealCategory) { save(() => api.updateMealCategory(category.id, { is_active: !category.is_active, updated_at: category.updated_at }), category.is_active ? 'Slot ausgeblendet.' : 'Slot eingeblendet.'); }
  function setCategoryPreset(categoryId: string, rank: number, recipeId: string) {
    const next = [...(categoryPresetIds[categoryId] ?? [])];
    if (recipeId) next[rank] = recipeId; else next.splice(rank, 1);
    categoryPresetIds = { ...categoryPresetIds, [categoryId]: next.filter((id, index, values) => id && values.indexOf(id) === index).slice(0, 2) };
  }
  function saveCategoryPresets(categoryId: string) { save(() => api.updateMealCategoryRecipePresets(categoryId, categoryPresetIds[categoryId] ?? []), 'Schnellauswahl gespeichert.'); }
  function foodPayloadFromDraft(draft: FoodDraft): Omit<Food, 'id'> { return { name: draft.name.trim(), kcal: nutrient(draft.kcal), protein_g: nutrient(draft.protein_g), carbs_g: nutrient(draft.carbs_g), fat_g: nutrient(draft.fat_g), fiber_g: nutrient(draft.fiber_g), sugar_g: nutrient(draft.sugar_g), free_sugar_g: nutrient(draft.free_sugar_g), saturated_fat_g: nutrient(draft.saturated_fat_g), sodium_mg: nutrient(draft.sodium_mg), potassium_mg: nutrient(draft.potassium_mg), calcium_mg: nutrient(draft.calcium_mg), magnesium_mg: nutrient(draft.magnesium_mg), iron_mg: nutrient(draft.iron_mg), zinc_mg: nutrient(draft.zinc_mg), vitamin_a_ug: nutrient(draft.vitamin_a_ug), vitamin_c_mg: nutrient(draft.vitamin_c_mg), vitamin_d_ug: nutrient(draft.vitamin_d_ug), vitamin_b12_ug: nutrient(draft.vitamin_b12_ug), folate_ug: nutrient(draft.folate_ug) }; }
  function addFood() { const name = foodDraft.name.trim(); const kcal = nutrient(foodDraft.kcal); if (!name || kcal == null) { error = 'Name und kcal pro 100 g sind erforderlich.'; return; } save(async () => { const value = await api.createFood(foodPayloadFromDraft(foodDraft)); if (value) foodDraft = emptyFood(); return value; }, 'Lebensmittel gespeichert.'); }
  function updateFood(food: Food) { save(() => api.updateFood(food.id, food), 'Lebensmittel und Nährwerte aktualisiert.'); }
  function enrichHistory() { save(() => api.enrichHistoricalMealNutrients(), 'Historische Mahlzeiten wurden mit den verfügbaren Nährstoffwerten aktualisiert.'); }
  function addIngredient(editing = false) { const id = editing ? editingRecipeFoodId : recipeFoodId; const quantity = Number(editing ? editingRecipeQuantity : recipeQuantity); if (!id || !Number.isFinite(quantity) || quantity <= 0) { error = 'Wähle ein Lebensmittel und eine gültige Grammmenge.'; return; } const ingredient = { food_id: id, quantity, unit: 'g' as const, sort_order: (editing ? editingRecipeDraft : recipeDraft).length }; if (editing) { editingRecipeDraft = [...editingRecipeDraft, ingredient]; editingRecipeFoodId = ''; } else { recipeDraft = [...recipeDraft, ingredient]; recipeFoodId = ''; } }
  function removeIngredient(index: number, editing = false) { const items = (editing ? editingRecipeDraft : recipeDraft).filter((_, current) => current !== index).map((item, sort_order) => ({ ...item, sort_order })); if (editing) editingRecipeDraft = items; else recipeDraft = items; }
  function createRecipe() { const name = recipeName.trim(); const servings = Number(recipeServings); if (!name || !Number.isFinite(servings) || servings <= 0 || !recipeDraft.length) { error = 'Ein Gericht braucht einen Namen, mindestens eine Portion und eine Zutat.'; return; } save(async () => { const value = await api.createRecipe({ name, servings, notes: recipeNotes.trim() || null, instructions: instructionSteps(recipeInstructions), status: 'active', ingredients: recipeDraft }); if (value) { recipeName = ''; recipeServings = '1'; recipeNotes = ''; recipeInstructions = ''; recipeDraft = []; } return value; }, 'Rezept gespeichert; die Nährwerte wurden aus den Zutaten berechnet.'); }
  function startRecipeEdit(recipe: Recipe) { editingRecipeId = recipe.id; editingRecipeDraft = recipe.ingredients.map((item, sort_order) => ({ ...item, sort_order })); editingRecipeFoodId = ''; editingRecipeQuantity = '100'; editingRecipeNotes = recipe.notes ?? ''; editingRecipeInstructions = (recipe.instructions ?? []).join('\n'); }
  function saveRecipe(recipe: Recipe) { if (!editingRecipeDraft.length) { error = 'Ein Rezept muss mindestens eine Zutat enthalten.'; return; } save(() => api.updateRecipe(recipe.id, { notes: editingRecipeNotes.trim() || null, instructions: instructionSteps(editingRecipeInstructions), ingredients: editingRecipeDraft, expected_updated_at: recipe.updated_at }), 'Rezept und Nährwerte aktualisiert.'); editingRecipeId = ''; }
  function archiveRecipe(recipe: Recipe) { save(() => api.updateRecipe(recipe.id, { status: recipe.status === 'archived' ? 'active' : 'archived', updated_at: recipe.updated_at }), recipe.status === 'archived' ? 'Rezept reaktiviert.' : 'Rezept archiviert.'); }

  function addPlan() { const name = planName.trim(); if (!name) { error = 'Bitte gib einen Namen für den Wochenplan ein.'; return; } save(async () => { const value = await api.createMealPlan({ name, is_active: plans.length === 0, items: [] }); if (value) planName = ''; return value; }, 'Wochenplan gespeichert.'); }
  function itemFor(items: MealPlanItem[], day: number, categoryId: string) { return items.find((item) => item.category_id === categoryId && item.weekdays?.includes(day)); }
  function openSlot(day: number, category: MealCategory) { const item = itemFor(planDraft, day, category.id); selectedSlot = { day, category }; slotRecipeId = item?.recipe_id ?? ''; slotPortion = String(item?.portion ?? 1); recipeSearch = ''; slotDialog?.showModal(); }
  async function persistPlanDraft(nextDraft: MealPlanItem[], success: string) {
    if (!selectedPlan) return;
    const previous = planDraft;
    planDraft = nextDraft;
    saving = true; error = ''; notice = '';
    try {
      const updated = await api.updateMealPlan(selectedPlan.id, { items: nextDraft.map(({ id: _id, ...item }) => item), expected_updated_at: selectedPlan.updated_at });
      if (!updated) throw new Error('empty');
      plans = plans.map((plan) => plan.id === updated.id ? updated : plan);
      hydratePlan(updated); notice = success;
    } catch { planDraft = previous; error = 'Der Wochenplan konnte nicht gespeichert werden. Bitte versuche es erneut.'; }
    finally { saving = false; }
  }
  function saveSlot() { if (!selectedSlot || !slotRecipeId) { error = 'Wähle ein Rezept aus.'; return; } const portion = Number(slotPortion); if (!Number.isFinite(portion) || portion <= 0) { error = 'Bitte gib eine gültige Portionszahl ein.'; return; } const { day, category } = selectedSlot; const existing = itemFor(planDraft, day, category.id); const next: MealPlanItem = { category_id: category.id, recipe_id: slotRecipeId, name: null, weekdays: [day], portion, sort_order: planDraft.length }; const draft = [...planDraft.filter((item) => item !== existing), next].map((item, sort_order) => ({ ...item, sort_order })); slotDialog.close(); persistPlanDraft(draft, 'Gericht im Wochenplan gespeichert.'); }
  function removeSlot() { if (!selectedSlot) return; const existing = itemFor(planDraft, selectedSlot.day, selectedSlot.category.id); if (!existing) return; const draft = planDraft.filter((item) => item !== existing).map((item, sort_order) => ({ ...item, sort_order })); slotDialog.close(); persistPlanDraft(draft, 'Gericht aus dem Wochenplan entfernt.'); }
  function savePlan() { if (!selectedPlan) return; save(() => api.updateMealPlan(selectedPlan.id, { items: planDraft.map(({ id: _id, ...item }) => item), expected_updated_at: selectedPlan.updated_at }), 'Wochenplan gespeichert.'); }
  function activatePlan(plan: MealPlan) { save(() => api.updateMealPlan(plan.id, { is_active: true, updated_at: plan.updated_at }), 'Plan aktiviert.'); }
</script>

<svelte:head><title>FitTrack – Mahlzeiten planen</title></svelte:head>
<div class="page">
  <SettingsHeader title="Mahlzeiten" subtitle="Plane die Woche, verwalte Rezepte bei Bedarf" />
  <nav class="section-nav" aria-label="Mahlzeitenbereich"><button class:active={section === 'plan'} aria-current={section === 'plan' ? 'page' : undefined} onclick={() => section = 'plan'}>Wochenplan</button><button class:active={section !== 'plan'} aria-current={section !== 'plan' ? 'page' : undefined} onclick={() => section = 'recipes'}>Verwalten</button></nav>
  {#if error}<div class="message error" role="alert">{error}</div>{/if}{#if notice}<div class="message success" role="status">{notice}</div>{/if}
  {#if loading}<div class="loading" role="status">Lade Mahlzeiten-Konfiguration…</div>
  {:else if section === 'plan'}
    <UiSurface><div class="surface-header"><div><h2>Wochenplan</h2><p>Wähle einen Slot, um Rezept oder Portion zu ändern.</p></div><span>{plans.length} gespeichert</span></div><div class="plan-controls">{#if plans.length}<label>Aktiver Entwurf<select aria-label="Wochenplan auswählen" value={selectedPlanId} onchange={(event) => { const plan = plans.find((value) => value.id === (event.currentTarget as HTMLSelectElement).value); if (plan) hydratePlan(plan); }}>{#each plans as plan (plan.id)}<option value={plan.id}>{plan.name}{plan.is_active ? ' · aktiv' : ''}</option>{/each}</select></label>{#if selectedPlan && !selectedPlan.is_active}<UiButton onclick={() => activatePlan(selectedPlan)}>Aktivieren</UiButton>{/if}<UiButton variant="primary" onclick={savePlan} disabled={saving}>Plan speichern</UiButton>{/if}<form class="new-plan" onsubmit={(event) => { event.preventDefault(); addPlan(); }}><input aria-label="Name des neuen Wochenplans" placeholder="Neuer Plan, z. B. Arbeitstage" bind:value={planName} maxlength="120" /><UiButton type="submit" disabled={saving}><Icon name="plus" size={16} />Plan anlegen</UiButton></form></div>{#if selectedPlan}<div class="mobile-days" aria-label="Tag auswählen">{#each DAYS as day, index}<button class:active={visibleDay === index} onclick={() => visibleDay = index}>{day.slice(0, 2)}</button>{/each}</div><div class="week-grid" aria-label={`Wochenplan ${selectedPlan.name}`}>{#each DAYS as day, dayIndex}<section class="day-column" class:mobile-hidden={dayIndex !== visibleDay} aria-label={day}><h3>{day}</h3>{#each activeCategories as category (category.id)}{@const item = itemFor(planDraft, dayIndex, category.id)}<button class="slot-button" class:filled={Boolean(item)} onclick={() => openSlot(dayIndex, category)} aria-label={`${category.name} am ${day}${item ? `: ${recipeNameFor(item.recipe_id)}, ${item.portion ?? 1} Portionen` : ': Rezept hinzufügen'}`}><span class="slot-category">{category.name}</span>{#if item}<strong>{recipeNameFor(item.recipe_id)}</strong><small>{item.portion ?? 1} Portion{Number(item.portion ?? 1) === 1 ? '' : 'en'}</small>{:else}<span class="slot-empty"><Icon name="plus" size={16} /> Rezept hinzufügen</span>{/if}</button>{:else}<p class="empty">Lege in „Verwalten“ zuerst Mahlzeiten-Slots an.</p>{/each}</section>{/each}</div>{:else}<div class="empty">Lege einen Wochenplan an, um deine Rezepte auf Tage und Mahlzeiten zu verteilen.</div>{/if}</UiSurface>
  {:else}
    <nav class="manage-nav" aria-label="Mahlzeiten verwalten"><button class:active={section === 'recipes'} onclick={() => section = 'recipes'}>Rezepte</button><button class:active={section === 'foods'} onclick={() => section = 'foods'}>Lebensmittel</button><button class:active={section === 'categories'} onclick={() => section = 'categories'}>Mahlzeiten-Slots</button></nav>
    {#if section === 'foods'}
      <div class="history-action"><UiButton type="button" onclick={enrichHistory} disabled={saving}>Historische Mahlzeiten anreichern</UiButton><p>Ergänzt fehlende Mikronährstoffe aus den aktuell gepflegten Lebensmittelwerten; bestehende Makro-Snapshots bleiben unverändert.</p></div>
      <UiSurface><div class="surface-header"><div><h2>Lebensmittel</h2><p>Alle Nährwerte gelten pro 100 g. Leere Werte bleiben unbekannt.</p></div><span>{foods.length} gespeichert</span></div><details class="create-details"><summary>Lebensmittel anlegen</summary><form class="food-form" onsubmit={(event) => { event.preventDefault(); addFood(); }}><input aria-label="Name" placeholder="z. B. Haferflocken" bind:value={foodDraft.name} maxlength="120" />{#each [['kcal','kcal'],['protein_g','Protein g'],['carbs_g','Kohlenhydrate g'],['fat_g','Fett g'],['fiber_g','Ballaststoffe g'],['sugar_g','Zucker g'],['free_sugar_g','Freie Zucker g'],['saturated_fat_g','Gesättigte Fettsäuren g'],['sodium_mg','Natrium mg'],['potassium_mg','Kalium mg'],['calcium_mg','Calcium mg'],['magnesium_mg','Magnesium mg'],['iron_mg','Eisen mg'],['zinc_mg','Zink mg'],['vitamin_a_ug','Vitamin A µg'],['vitamin_c_mg','Vitamin C mg'],['vitamin_d_ug','Vitamin D µg'],['vitamin_b12_ug','Vitamin B12 µg'],['folate_ug','Folat µg']] as [key, label]}<input aria-label={`${label} pro 100 Gramm`} type="number" min="0" step="0.001" placeholder={label} bind:value={foodDraft[key as keyof FoodDraft]} />{/each}<UiButton variant="primary" type="submit" disabled={saving}>Speichern</UiButton></form></details><div class="list">{#each foods as food (food.id)}<details class="food-row"><summary><div><strong>{food.name}</strong><small>{food.kcal ?? '–'} kcal · P {food.protein_g ?? '–'} g · KH {food.carbs_g ?? '–'} g · F {food.fat_g ?? '–'} g / 100 g</small></div><span>Nährwerte bearbeiten</span></summary><form class="food-form food-edit" onsubmit={(event) => { event.preventDefault(); updateFood(food); }}><input aria-label={`${food.name}: Name`} bind:value={food.name} maxlength="120" />{#each [['kcal','kcal'],['protein_g','Protein g'],['carbs_g','Kohlenhydrate g'],['fat_g','Fett g'],['fiber_g','Ballaststoffe g'],['sugar_g','Zucker g'],['free_sugar_g','Freie Zucker g'],['saturated_fat_g','Gesättigte Fettsäuren g'],['sodium_mg','Natrium mg'],['potassium_mg','Kalium mg'],['calcium_mg','Calcium mg'],['magnesium_mg','Magnesium mg'],['iron_mg','Eisen mg'],['zinc_mg','Zink mg'],['vitamin_a_ug','Vitamin A µg'],['vitamin_c_mg','Vitamin C mg'],['vitamin_d_ug','Vitamin D µg'],['vitamin_b12_ug','Vitamin B12 µg'],['folate_ug','Folat µg']] as [key, label]}<label>{label}<input aria-label={`${food.name}: ${label} pro 100 Gramm`} type="number" min="0" step="0.001" bind:value={food[key as keyof Food]}/></label>{/each}<UiButton variant="primary" type="submit" disabled={saving}>Nährwerte speichern</UiButton></form></details>{:else}<div class="empty">Noch keine Lebensmittel.</div>{/each}</div></UiSurface>
    {:else if section === 'recipes'}
<UiSurface><div class="surface-header"><div><h2>Rezepte</h2><p>Gerichte bestehen aus Zutaten; Nährwerte werden automatisch berechnet.</p></div><span>{activeRecipes.length} aktiv</span></div><details class="create-details"><summary>Rezept anlegen</summary><form class="recipe-editor" onsubmit={(event) => { event.preventDefault(); createRecipe(); }}><div class="form-row"><input aria-label="Rezeptname" placeholder="z. B. Protein-Porridge" bind:value={recipeName} maxlength="120" /><input aria-label="Anzahl Portionen" type="number" min="0.001" step="0.001" bind:value={recipeServings} /></div><textarea aria-label="Notizen" placeholder="Notizen (optional)" bind:value={recipeNotes}></textarea><textarea aria-label="Kochanleitung" placeholder="Kochanleitung – ein Schritt pro Zeile" bind:value={recipeInstructions}></textarea><div class="ingredient-add"><select aria-label="Lebensmittel" bind:value={recipeFoodId}><option value="">Lebensmittel auswählen…</option>{#each foods as food}<option value={food.id}>{food.name}</option>{/each}</select><input aria-label="Menge in Gramm" type="number" min="0.001" step="0.001" bind:value={recipeQuantity} /><UiButton onclick={() => addIngredient()}>Zutat hinzufügen</UiButton></div><div class="ingredient-list">{#each recipeDraft as ingredient, index}<div><span>{foodName(ingredient.food_id)} · {ingredient.quantity} g</span><button type="button" aria-label={`${foodName(ingredient.food_id)} entfernen`} onclick={() => removeIngredient(index)}>×</button></div>{:else}<small>Mindestens eine Zutat erforderlich.</small>{/each}</div><UiButton variant="primary" type="submit" disabled={saving}>Rezept speichern</UiButton></form></details><div class="list">{#each recipes as recipe (recipe.id)}<article class:archived={recipe.status === 'archived'} class="recipe-row">{#if editingRecipeId === recipe.id}<form class="recipe-editor" onsubmit={(event) => { event.preventDefault(); saveRecipe(recipe); }}><strong>{recipe.name} · {recipe.servings} Portion{Number(recipe.servings) === 1 ? '' : 'en'}</strong><textarea aria-label="Notizen" bind:value={editingRecipeNotes}></textarea><textarea aria-label="Kochanleitung" placeholder="Kochanleitung – ein Schritt pro Zeile" bind:value={editingRecipeInstructions}></textarea><div class="ingredient-add"><select aria-label="Lebensmittel" bind:value={editingRecipeFoodId}><option value="">Lebensmittel auswählen…</option>{#each foods as food}<option value={food.id}>{food.name}</option>{/each}</select><input aria-label="Menge in Gramm" type="number" min="0.001" step="0.001" bind:value={editingRecipeQuantity} /><UiButton onclick={() => addIngredient(true)}>Hinzufügen</UiButton></div><div class="ingredient-list">{#each editingRecipeDraft as ingredient, index}<div><span>{foodName(ingredient.food_id)} · {ingredient.quantity} g</span><button type="button" aria-label={`${foodName(ingredient.food_id)} entfernen`} onclick={() => removeIngredient(index, true)}>×</button></div>{/each}</div><div class="actions"><UiButton variant="primary" type="submit" disabled={saving}>Speichern</UiButton><UiButton onclick={() => editingRecipeId = ''}>Abbrechen</UiButton></div></form>{:else}<div class="row-main"><strong>{recipe.name}</strong><small>{recipe.ingredients.map((ingredient) => `${foodName(ingredient.food_id)} (${ingredient.quantity} g)`).join(' · ')}</small><small>{nutrition(recipe)} pro Portion{#if recipe.notes} · {recipe.notes}{/if}</small></div><div class="actions"><UiButton onclick={() => startRecipeEdit(recipe)}>Bearbeiten</UiButton><UiButton onclick={() => archiveRecipe(recipe)}>{recipe.status === 'archived' ? 'Reaktivieren' : 'Archivieren'}</UiButton></div>{/if}</article>{:else}<div class="empty">Noch kein Rezept. Lege Lebensmittel an und erstelle daraus dein erstes Gericht.</div>{/each}</div></UiSurface>
    {:else}
      <UiSurface><div class="surface-header"><div><h2>Mahlzeiten-Slots</h2><p>Zum Beispiel Frühstück, Mittagessen oder Snack.</p></div><span>{activeCategories.length} aktiv</span></div><form class="form-row add-slot" onsubmit={(event) => { event.preventDefault(); addCategory(); }}><input aria-label="Name des neuen Slots" placeholder="z. B. Frühstück" bind:value={categoryName} maxlength="80" /><UiButton variant="primary" type="submit" disabled={saving}>Slot hinzufügen</UiButton></form><div class="list">{#each categories as category, index (category.id)}<div class:archived={!category.is_active} class="row category-row"><div><strong>{category.name}</strong><small>{category.is_active ? 'im Plan sichtbar' : 'ausgeblendet'}</small><div class="preset-fields"><label>Standard 1<select value={categoryPresetIds[category.id]?.[0] ?? ''} onchange={(event) => setCategoryPreset(category.id, 0, (event.currentTarget as HTMLSelectElement).value)}><option value="">Nicht festgelegt</option>{#each activeRecipes as recipe (recipe.id)}<option value={recipe.id}>{recipe.name}</option>{/each}</select></label><label>Standard 2<select value={categoryPresetIds[category.id]?.[1] ?? ''} onchange={(event) => setCategoryPreset(category.id, 1, (event.currentTarget as HTMLSelectElement).value)}><option value="">Nicht festgelegt</option>{#each activeRecipes as recipe (recipe.id)}<option value={recipe.id}>{recipe.name}</option>{/each}</select></label><UiButton onclick={() => saveCategoryPresets(category.id)} disabled={saving}>Schnellauswahl speichern</UiButton></div></div><div class="actions"><UiButton disabled={index === 0 || saving} onclick={() => moveCategory(index, -1)}>Nach oben</UiButton><UiButton disabled={index === categories.length - 1 || saving} onclick={() => moveCategory(index, 1)}>Nach unten</UiButton><UiButton onclick={() => setCategoryActive(category)}>{category.is_active ? 'Ausblenden' : 'Einblenden'}</UiButton></div></div>{:else}<div class="empty">Lege mindestens einen Slot an, bevor du planst.</div>{/each}</div></UiSurface>
    {/if}
  {/if}
</div>

<dialog bind:this={slotDialog} class="slot-dialog" aria-labelledby="slot-dialog-title" onclose={() => selectedSlot = null}>{#if selectedSlot}<form method="dialog" onsubmit={(event) => { event.preventDefault(); saveSlot(); }}><header><div><p>{DAYS[selectedSlot.day]} · {selectedSlot.category.name}</p><h2 id="slot-dialog-title">Mahlzeit planen</h2></div><button class="close" type="button" aria-label="Schließen" onclick={() => slotDialog.close()}><Icon name="x" size={20} /></button></header><label>Rezept suchen<input aria-label="Rezept suchen" placeholder="Name eingeben…" bind:value={recipeSearch} autocomplete="off" /></label><div class="recipe-picker" role="listbox" aria-label="Verfügbare Rezepte">{#each filteredSlotRecipes as recipe (recipe.id)}<button type="button" class:chosen={slotRecipeId === recipe.id} onclick={() => slotRecipeId = recipe.id} role="option" aria-selected={slotRecipeId === recipe.id}><strong>{recipe.name}</strong><small>{nutrition(recipe)}</small></button>{:else}<p>Kein passendes Rezept gefunden.</p>{/each}</div><label>Portionen<input type="number" min="0.001" step="0.001" bind:value={slotPortion} /></label><div class="dialog-actions">{#if itemFor(planDraft, selectedSlot.day, selectedSlot.category.id)}<UiButton variant="danger" type="button" onclick={removeSlot} disabled={saving}>Aus Plan entfernen</UiButton>{/if}<span></span><UiButton type="button" onclick={() => slotDialog.close()}>Abbrechen</UiButton><UiButton variant="primary" type="submit" disabled={saving}>Übernehmen</UiButton></div></form>{/if}</dialog>

<style>
  .page { display:grid; gap:var(--space-3); min-width:0; padding-bottom:24px; } h2,h3,p { margin:0; } h2 { font-size:16px; } h3 { font-size:13px; } button,input,select,textarea { font:inherit; } button { cursor:pointer; } input,select,textarea { width:100%; min-height:var(--control-min); border:1px solid var(--border-default); border-radius:var(--radius-control); background:var(--surface-raised); color:var(--text-primary); padding:8px 10px; } textarea { min-height:76px; resize:vertical; } small,.surface-header p { color:var(--text-tertiary); font-size:12px; line-height:1.4; } .section-nav,.manage-nav,.mobile-days { display:flex; gap:6px; overflow-x:auto; padding-bottom:2px; } .section-nav button,.manage-nav button,.mobile-days button { min-height:38px; border:1px solid var(--border-default); border-radius:var(--radius-full); background:var(--surface-default); color:var(--text-secondary); padding:7px 13px; white-space:nowrap; } .section-nav button.active,.manage-nav button.active,.mobile-days button.active { background:var(--status-success); border-color:var(--status-success); color:var(--text-on-accent); font-weight:700; } .surface-header { display:flex; justify-content:space-between; align-items:flex-start; gap:var(--space-3); padding:var(--space-4); border-bottom:1px solid var(--border-subtle); } .surface-header > span { color:var(--text-tertiary); font-size:12px; white-space:nowrap; } .plan-controls { display:flex; align-items:end; flex-wrap:wrap; gap:var(--space-2); padding:var(--space-3) var(--space-4); border-bottom:1px solid var(--border-subtle); } .plan-controls label { display:grid; flex:1 1 210px; gap:4px; color:var(--text-secondary); font-size:12px; } .new-plan { display:flex; flex:1 1 270px; gap:var(--space-2); } .new-plan input { min-width:0; } .mobile-days { display:none; padding:var(--space-3) var(--space-4) 0; } .week-grid { display:grid; grid-template-columns:repeat(7,minmax(132px,1fr)); gap:8px; overflow-x:auto; padding:var(--space-4); } .day-column { display:grid; align-content:start; gap:7px; min-width:132px; } .day-column h3 { padding:0 3px 3px; } .slot-button { display:grid; width:100%; min-height:92px; align-content:start; gap:5px; text-align:left; border:1px dashed var(--border-default); border-radius:var(--radius-surface); background:var(--surface-raised); color:var(--text-primary); padding:10px; } .slot-button.filled { border-style:solid; border-color:color-mix(in srgb,var(--status-success) 56%,var(--border-default)); background:color-mix(in srgb,var(--status-success) 5%,var(--surface-raised)); } .slot-button:active { background:var(--surface-pressed); } .slot-category { color:var(--text-tertiary); font-size:11px; } .slot-button strong { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:13px; } .slot-empty { display:flex; align-items:center; gap:5px; color:var(--text-secondary); font-size:12px; } .message,.loading,.empty { padding:var(--space-4); font-size:13px; line-height:1.45; } .message { border-radius:var(--radius-control); } .error { color:var(--status-danger); background:color-mix(in srgb,var(--status-danger) 12%,transparent); } .success { color:var(--status-success); background:color-mix(in srgb,var(--status-success) 12%,transparent); } .empty,.loading { color:var(--text-tertiary); } .create-details { border-bottom:1px solid var(--border-subtle); } .create-details summary { min-height:46px; display:flex; align-items:center; cursor:pointer; padding:0 var(--space-4); color:var(--status-success); font-size:13px; font-weight:650; } .food-form,.recipe-editor { display:grid; gap:var(--space-2); padding:0 var(--space-4) var(--space-4); } .food-form { grid-template-columns:minmax(170px,2fr) repeat(5,minmax(92px,1fr)) auto; } .form-row,.ingredient-add,.actions { display:flex; gap:var(--space-2); align-items:center; } .form-row input,.ingredient-add select { flex:1; } .form-row input:last-child { max-width:120px; } .ingredient-add input { width:110px; } .ingredient-list { display:grid; gap:4px; padding:8px; border-radius:var(--radius-control); background:var(--surface-raised); } .ingredient-list div { display:flex; justify-content:space-between; align-items:center; gap:8px; font-size:13px; } .ingredient-list button { min-width:30px; min-height:30px; color:var(--status-danger); font-size:20px; } .list { border-top:1px solid var(--border-subtle); } .row,.recipe-row { display:flex; align-items:center; gap:var(--space-2); padding:12px var(--space-4); border-bottom:1px solid var(--border-subtle); } .recipe-row { align-items:flex-start; } .row > div:first-child,.row-main { display:grid; flex:1; min-width:0; gap:3px; } .row-main small { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; } .actions { flex-wrap:wrap; justify-content:flex-end; } .archived { opacity:.55; } .add-slot { padding:var(--space-3) var(--space-4); } .slot-dialog { width:min(100% - 24px,480px); max-height:min(82dvh,560px); margin:auto; border:1px solid var(--border-default); border-radius:var(--radius-modal); background:var(--surface-default); color:var(--text-primary); box-shadow:var(--shadow-modal); } .slot-dialog::backdrop { background:var(--overlay-backdrop); } .slot-dialog form { display:grid; gap:var(--space-3); padding:var(--space-4); } .slot-dialog header { display:flex; justify-content:space-between; gap:var(--space-3); } .slot-dialog header p { color:var(--text-tertiary); font-size:12px; } .slot-dialog label { display:grid; gap:5px; color:var(--text-secondary); font-size:12px; } .close { display:grid; place-items:center; width:38px; height:38px; flex:0 0 auto; border-radius:var(--radius-control); color:var(--text-secondary); } .close:active { background:var(--surface-raised); } .dialog-actions { display:grid; grid-template-columns:auto 1fr auto auto; align-items:center; gap:var(--space-2); padding-top:var(--space-2); } @media(max-width:760px) { .plan-controls { align-items:stretch; } .mobile-days { display:flex; } .week-grid { display:block; overflow:visible; padding-top:var(--space-3); } .day-column { min-width:0; } .day-column.mobile-hidden { display:none; } .food-form { grid-template-columns:repeat(2,minmax(0,1fr)); } .food-form input:first-child { grid-column:span 2; } } @media(max-width:480px) { .new-plan,.form-row,.ingredient-add { flex-wrap:wrap; } .row,.recipe-row { align-items:flex-start; flex-direction:column; } .actions { width:100%; justify-content:flex-start; } .dialog-actions { grid-template-columns:1fr 1fr; } .dialog-actions span { display:none; } }
  .history-action { display:grid; gap:var(--space-2); padding:var(--space-3); border:1px solid var(--border-subtle); border-radius:var(--radius-surface); background:var(--surface-raised); } .history-action p { color:var(--text-secondary); font-size:12px; line-height:1.45; } .food-form { grid-template-columns:repeat(auto-fit,minmax(130px,1fr)); align-items:end; } .food-form > input:first-child { grid-column:span 2; } .food-row { border-bottom:1px solid var(--border-subtle); } .food-row summary { display:flex; align-items:center; justify-content:space-between; gap:var(--space-3); min-height:62px; padding:10px var(--space-4); cursor:pointer; } .food-row summary > div { display:grid; gap:3px; min-width:0; } .food-row summary span { color:var(--status-success); font-size:12px; white-space:nowrap; } .food-edit { padding-top:0; } .food-edit label { display:grid; gap:4px; color:var(--text-secondary); font-size:11px; } .preset-fields { display:grid; grid-template-columns:repeat(2,minmax(150px,1fr)) auto; align-items:end; gap:var(--space-2); margin-top:var(--space-2); } .preset-fields label { display:grid; gap:4px; color:var(--text-tertiary); font-size:11px; } .preset-fields select { min-width:0; } .recipe-picker { display:grid; gap:6px; max-height:280px; overflow:auto; padding:4px; border:1px solid var(--border-default); border-radius:var(--radius-control); background:var(--surface-raised); } .recipe-picker button { display:grid; gap:3px; width:100%; min-height:58px; padding:9px 10px; text-align:left; border:1px solid transparent; border-radius:calc(var(--radius-control) - 2px); background:transparent; color:var(--text-primary); } .recipe-picker button.chosen { border-color:var(--status-success); background:color-mix(in srgb,var(--status-success) 11%,transparent); } .recipe-picker small,.recipe-picker p { margin:0; color:var(--text-tertiary); font-size:12px; } @media(max-width:480px) { .food-form > input:first-child { grid-column:span 1; } .food-row summary { align-items:flex-start; flex-direction:column; } .slot-dialog { width:100%; max-width:none; max-height:100dvh; border-radius:var(--radius-modal) var(--radius-modal) 0 0; margin:auto 0 0; } .recipe-picker { max-height:calc(100dvh - 285px); } }
</style>
